using System;
using System.Collections.Generic;
using System.Linq;
using AICad.Contracts;
using JsonUtil=AICad.Contracts.Json;
namespace AICad.Geometry;
public static class Validation {
 public static readonly string[] Tools={"draw_wall","draw_line","draw_polyline","draw_circle","draw_arc","add_text","insert_block","add_dimension","create_hatch"};
 public static void Finite(double n){if(double.IsNaN(n)||double.IsInfinity(n)||Math.Abs(n)>1e8)throw new CadException("INVALID_GEOMETRY","Coordinates must be finite and bounded.");}
 public static double Cross(Point2 a,Point2 b,Point2 p)=>(b.X-a.X)*(p.Y-a.Y)-(b.Y-a.Y)*(p.X-a.X);
 public static bool Contains(IReadOnlyList<Point2> poly,Point2 p){int sign=0;for(int i=0;i<poly.Count;i++){double c=Cross(poly[i],poly[(i+1)%poly.Count],p);if(Math.Abs(c)<1e-6)continue;int s=c>0?1:-1;if(sign!=0&&sign!=s)return false;sign=s;}return sign!=0;}
 public static void Scope(IReadOnlyList<Point2> points){if(points==null||points.Count<3||points.Count>32)throw new CadException("INVALID_SCOPE","A convex boundary with 3–32 vertices is required.");foreach(var p in points){if(p==null)throw new CadException("INVALID_SCOPE","Null vertex.");Finite(p.X);Finite(p.Y);}int sign=0;for(int i=0;i<points.Count;i++){double c=Cross(points[i],points[(i+1)%points.Count],points[(i+2)%points.Count]);if(Math.Abs(c)<1e-6)throw new CadException("INVALID_SCOPE","Degenerate boundary.");int s=c>0?1:-1;if(sign!=0&&sign!=s)throw new CadException("UNSUPPORTED_SCOPE","Concave boundaries require a clipping implementation.");sign=s;}foreach(var p in points)if(!Contains(points,p))throw new CadException("INVALID_SCOPE","Self-intersecting boundary.");}
 public static void Template(TemplateProfile t){JsonUtil.Name(t.Id);if(!Version.TryParse(t.Version,out _)||t.Units!="mm"||t.Layers==null||t.Blocks==null||t.Layers.Count<1||t.Layers.Count>100||t.Blocks.Count>1000)throw new CadException("INVALID_TEMPLATE","Invalid template metadata.");if(t.TextHeight<10||t.TextHeight>500||t.ArrowSize<1||t.ArrowSize>300||!System.Text.RegularExpressions.Regex.IsMatch(t.Font??"",@"^[a-zA-Z0-9_-]{1,60}\.(shx|ttf)$",System.Text.RegularExpressions.RegexOptions.IgnoreCase))throw new CadException("INVALID_TEMPLATE","Bounded style settings and a safe SHX/TTF filename required.");if(t.Layers.Select(l=>l.Name).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=t.Layers.Count||t.Blocks.Select(b=>b.Id).Distinct().Count()!=t.Blocks.Count)throw new CadException("INVALID_TEMPLATE","Duplicate resource ID.");foreach(var l in t.Layers){JsonUtil.LayerName(l.Name);if(l.Appearance!=null){var a=l.Appearance;JsonUtil.LayerName(a.LineType);if(a.SourceHash!=""&&!System.Text.RegularExpressions.Regex.IsMatch(a.SourceHash,"^[a-f0-9]{64}$")||a.Rgb<0||a.Rgb>0xffffff||!new[]{-3,-2,-1,0,5,9,13,15,18,20,25,30,35,40,50,53,60,70,80,90,100,106,120,140,158,200,211}.Contains(a.LineWeight))throw new CadException("INVALID_LAYER","Thuộc tính layer không hợp lệ.");if(a.Dashes!=null){if(a.Dashes.Count>100)throw new CadException("INVALID_LAYER","Mẫu nét quá dài.");foreach(double dash in a.Dashes)Finite(dash);}if(a.PatternLength.HasValue)Finite(a.PatternLength.Value);}if(l.Color<1||l.Color>255)throw new CadException("INVALID_TEMPLATE","Invalid ACI color.");}foreach(var b in t.Blocks){JsonUtil.Name(b.Id);DraftingRules.Asset(b,t);if(b.NativeSource!=null){var n=b.NativeSource;if(!System.Text.RegularExpressions.Regex.IsMatch(n.FileHash??"","^[a-f0-9]{64}$")||string.IsNullOrWhiteSpace(n.BlockName)||n.BlockName.Length>255||n.BlockName.Any(char.IsControl))throw new CadException("INVALID_ASSET","Invalid native CAD source.");if(n.Min==null||n.Max==null)throw new CadException("INVALID_ASSET","Native asset bounds required.");Finite(n.Min.X);Finite(n.Min.Y);Finite(n.Max.X);Finite(n.Max.Y);if(n.Min.X>n.Max.X||n.Min.Y>n.Max.Y||n.Min.X==n.Max.X&&n.Min.Y==n.Max.Y)throw new CadException("INVALID_ASSET","Invalid native asset extents.");if(b.Geometry==null||b.Geometry.Count!=0)throw new CadException("INVALID_ASSET","Native assets cannot also redefine geometry.");continue;}if(b.Geometry==null||b.Geometry.Count<1||b.Geometry.Count>100)throw new CadException("INVALID_TEMPLATE","Invalid block geometry.");foreach(var op in b.Geometry){if(op.Kind=="insert_block"||op.Kind=="create_hatch"||op.Kind=="add_dimension")throw new CadException("INVALID_TEMPLATE","Block definitions contain primitives only.");Operation(op,t,false);}}}
 public static void Plan(DrawingPlan p){if(p==null||p.SchemaVersion!=1||p.Space!="Model"||p.Units!="mm")throw new CadException("UNSUPPORTED_PLAN","Model space in mm required.");JsonUtil.Id(p.PlanId);JsonUtil.Id(p.SessionId);JsonUtil.Id(p.DocumentId);JsonUtil.Name(p.TaskId);if(string.IsNullOrEmpty(p.DocumentRevision)||p.CreatedUtc>DateTime.UtcNow.AddMinutes(1)||p.CreatedUtc<DateTime.UtcNow.AddHours(-24))throw new CadException("STALE_PLAN","Invalid or expired plan.");Scope(p.Scope);if(p.Operations==null||p.Operations.Count<1||p.Operations.Count>500)throw new CadException("PLAN_LIMIT","Plan requires 1–500 operations.");Template(p.Template);if(JsonUtil.Hash(p.Template)!=p.TemplateHash)throw new CadException("RESOURCE_CHANGED","Template snapshot hash differs.");if(p.Sources.Count>10||p.Assumptions.Count>50)throw new CadException("PLAN_LIMIT","Too many source/assumption bindings.");foreach(var op in p.Operations){Operation(op,p.Template,true);foreach(var point in Bounds(op,p.Template))if(!Contains(p.Scope,point))throw new CadException("OUTSIDE_SCOPE","Operation may extend beyond task boundary.");}}
 public static void Operation(Operation op,TemplateProfile t,bool demandLayer)=>Operation(op,t,demandLayer,false);
 public static void Operation(Operation op,TemplateProfile t,bool demandLayer,bool draft){if(op==null||!Tools.Contains(op.Kind))throw new CadException("UNSUPPORTED_TOOL",op?.Kind??"null");if(op.Points==null||op.Points.Count>2000)throw new CadException("GEOMETRY_LIMIT","Invalid vertex count.");foreach(var p in op.Points){if(p==null)throw new CadException("INVALID_GEOMETRY","Null point.");Finite(p.X);Finite(p.Y);}Finite(op.Radius);Finite(op.Rotation);Finite(op.Height);Finite(op.PatternScale);if((op.Kind=="draw_wall"||op.Kind=="draw_line")&&op.Points.Count!=2||op.Kind=="draw_polyline"&&op.Points.Count<2||op.Kind=="create_hatch"&&op.Points.Count<3||op.Kind=="add_dimension"&&op.Points.Count!=3||new[]{"draw_circle","draw_arc","add_text","insert_block"}.Contains(op.Kind)&&op.Points.Count!=1)throw new CadException("INVALID_GEOMETRY","Wrong point count.");if((op.Kind=="draw_circle"||op.Kind=="draw_arc")&&op.Radius<=0)throw new CadException("INVALID_GEOMETRY","Positive radius required.");if(op.Kind=="add_text"&&(string.IsNullOrEmpty(op.Text)||op.Text.Length>120||op.Text.Any(char.IsControl)||op.Text.Contains("%<")||op.Height<=0||op.Height>1000))throw new CadException("INVALID_TEXT","Bounded plain text required.");if(op.Kind=="add_dimension"&&(Distance(op.Points[0],op.Points[1])<1e-6||op.Text!=""&&op.Text!="<>"))throw new CadException("INVALID_DIMENSION","Numerical dimension overrides are forbidden.");if(op.Kind=="create_hatch"){Scope(op.Points);if(!new[]{"ANSI31","SOLID"}.Contains(op.Pattern)||op.PatternScale<1||op.PatternScale>1000)throw new CadException("INVALID_HATCH","Supported hatch pattern/scale required.");}if(op.Kind=="insert_block"&&!t.Blocks.Any(b=>b.Id==op.AssetId))throw new CadException("MISSING_ASSET",op.AssetId);if(op.SymbolScale!=null||op.AttributeText!=null){
  var label=op.Kind=="insert_block"?t.Blocks.Single(b=>b.Id==op.AssetId).NativeSource?.LabelAttribute:null;
  if(string.IsNullOrEmpty(label)||op.SymbolScale is not (>=10 and <=200)||string.IsNullOrEmpty(op.AttributeText)||op.AttributeText!.Length>8||op.AttributeText.Any(c=>!char.IsLetterOrDigit(c)))
   throw new CadException("INVALID_AXIS_SYMBOL","Ký hiệu ATT hoặc tỷ lệ ký hiệu không hợp lệ.");
 }DraftingRules.Operation(op,t,draft);if(demandLayer&&!t.Layers.Any(l=>l.Name==op.Layer))throw new CadException("MISSING_LAYER",op.Layer);}
 public static double Distance(Point2 a,Point2 b)=>Math.Sqrt((a.X-b.X)*(a.X-b.X)+(a.Y-b.Y)*(a.Y-b.Y));
 public static IEnumerable<Point2> Bounds(Operation op,TemplateProfile t){if(op.Kind=="draw_wall"){foreach(var p in DraftingRules.Wall(op))yield return p;yield break;}if(op.Kind=="insert_block"){var o=op.Points[0];var native=t.Blocks.Single(b=>b.Id==op.AssetId).NativeSource;if(native!=null){if(op.SymbolScale==null&&(op.DynamicJson!=null||op.OpeningWidth!=null||op.WallThickness!=null||t.Blocks.Single(b=>b.Id==op.AssetId).Usage!=null)){yield return o;yield break;}foreach(var q in Box(native.Min.X,native.Min.Y,native.Max.X,native.Max.Y))yield return Rotate(new Point2(q.X*(op.SymbolScale??1),q.Y*(op.SymbolScale??1)),o,op.Rotation);yield break;}foreach(var child in t.Blocks.Single(b=>b.Id==op.AssetId).Geometry)foreach(var p in Bounds(child,t))yield return Rotate(p,o,op.Rotation);yield break;}if(op.Kind=="draw_circle"||op.Kind=="draw_arc"){var p=op.Points[0];foreach(var q in Box(p.X-op.Radius,p.Y-op.Radius,p.X+op.Radius,p.Y+op.Radius))yield return q;yield break;}if(op.Kind=="add_text"){double w=op.Text.Length*op.Height*1.5;foreach(var q in Box(-op.Height,-op.Height,w,op.Height*2))yield return Rotate(q,op.Points[0],op.Rotation);yield break;}if(op.Kind=="add_dimension"){double m=t.TextHeight*4;foreach(var q in Box(op.Points.Min(p=>p.X)-m,op.Points.Min(p=>p.Y)-m,op.Points.Max(p=>p.X)+m,op.Points.Max(p=>p.Y)+m))yield return q;yield break;}foreach(var p in op.Points)yield return p;}
 public static Point2 Rotate(Point2 p,Point2 o,double a)=>new(o.X+p.X*Math.Cos(a)-p.Y*Math.Sin(a),o.Y+p.X*Math.Sin(a)+p.Y*Math.Cos(a));
 public static IEnumerable<Point2> Box(double x0,double y0,double x1,double y1){yield return new(x0,y0);yield return new(x1,y0);yield return new(x1,y1);yield return new(x0,y1);}
}
